protected override void OnBarUpdate()
{
    // === DIAG PATCH START ===
    bool VerboseDiag = true; // Default to true for SA Backtest ground truth
    try
    {
        if (VerboseDiag)
        {
            bool inWindow = (DateTime.Now.Hour >= SessionStartHour && DateTime.Now.Hour < SessionEndHour);
            int logFrequency = inWindow ? 10 : 100;
            bool isDecisionBar = (1 == EnterShort() || 1 == EnterLong() || 1 == ExitLong() || 1 == ExitShort());

            if (CurrentBar % logFrequency == 0 || isDecisionBar)
            {
                string diag = string.Format(
                    "[DIAG] Bar:{0} | Time:{1} | Price:{2} | Window:{3} | ORH:{4} | ORL:{5} | RangeC:{6} | Dir:{7} | BiasReq:{8} | BiasBlk:{9} | GT_RH:{10} | LT_RL:{11} | GK_Blk:{12}",
                    CurrentBar,
                    Time[0],
                    Close[0],
                    inWindow,
                    or_high,
                    or_low,
                    range_complete,
                    predicted_dir,
                    require_direction_bias,
                    bias_blocked,
                    Close[0] > or_high,
                    Close[0] < or_low,
                    (Account.Name.Contains("backtest") || Account.Name.Contains("Playback") ? "Bypass" : gatekeeper_blocked.ToString())
                );

                Log(diag, LogLevel.Information);

                if (isDecisionBar)
                {
                    Log("[DIAG] EXECUTION: Trade decision triggered on bar " + CurrentBar, LogLevel.Information);
                }
            }
        }
    }
    catch (Exception ex)
    {
        Log("[DIAG ERROR] " + ex.Message, LogLevel.Error);
    }
    // === DIAG PATCH END ===

    // ... Existing strategy logic follows ...
}
